.step-indicator ol {
    counter-reset: step;
}

.step-item {
    position: relative;
    z-index: 1;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
}

.completed-circle {
    background-color: #198754;
    color: white;
    border: none;
    padding: 0;
    cursor: pointer;
    width: 36px;
    height: 36px;
    border-radius: 50%;
}

.completed-circle:hover {
    background-color: #157347;
}

.current-circle {
    background-color: #0d6efd;
    color: white;
    border: 2px solid #0d6efd;
}

.future-circle {
    background-color: #e9ecef;
    color: #6c757d;
    border: 2px solid #dee2e6;
}

.step-label {
    font-size: 0.75rem;
}

.dimmed .step-label {
    color: #adb5bd;
}

.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.completed .step-label {
    color: #198754;
}

.checkmark {
    font-size: 1rem;
}

