@page "/apply"
@using sv_705de9ee57704264a2f40d2a229e3a9d.Components.JobApplication
@using sv_705de9ee57704264a2f40d2a229e3a9d.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (submittedId.HasValue)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">✓ Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p><strong>Application ID: @submittedId.Value</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="mt-4">
            @switch (currentStep)
            {
                case 0:
                    <PersonalInfoStep Model="personalInfo"
                                      ApplicationService="ApplicationService"
                                      OnNext="NextStep" />
                    break;
                case 1:
                    <WorkHistoryStep Entries="workEntries"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 2:
                    <ReferencesStep References="references"
                                    OnNext="NextStep"
                                    OnBack="PreviousStep" />
                    break;
                case 3:
                    <CoverLetterStep @bind-CoverLetter="coverLetter"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 4:
                    <ReviewStep Personal="personalInfo"
                                WorkEntries="workEntries"
                                References="references"
                                CoverLetter="coverLetter"
                                IsSubmitting="isSubmitting"
                                ErrorMessage="submitError"
                                OnBack="PreviousStep"
                                OnEditStep="GoToStep"
                                OnSubmit="SubmitApplication" />
                    break;
            }
        </div>
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;
    private readonly HashSet<int> completedSteps = new();

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private string? submitError;
    private int? submittedId;

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

